insert into public.flatmate_profiles (id, user_id, bio, budget_min, budget_max, preferred_areas, looking_for, move_in, lifestyle, gender_preference, has_place, listing_id, languages, work_area, workplace_id, updated_at) values
  ('b2911ee1-1064-4860-a715-ed2f4f7b6e4b', '68486ed1-5802-4365-a023-eec50b9d4d18', 'Backend engineer, early riser, runs on weekends. Looking for someone easy-going who keeps the kitchen clean.', 12000, 15000, array['gurgaon-sector-52', 'dlf-phase-3', 'sushant-lok']::text[], array['2BHK']::text[], (now() + interval '2192008 seconds')::date, array['NON_SMOKER', 'EARLY_RISER', 'VERY_CLEAN']::text[], 'ANY', false, null, array['English', 'Hindi', 'Punjabi']::text[], 'Cyber City, Gurugram', 'cyber-city', now() - interval '3600 seconds'),
  ('87b4a74c-a045-4f4d-accf-d1c69a28377e', '06638bf4-732a-4924-ab25-e752b3b15308', 'From Kochi, working in Aerocity. Vegetarian household preferred, I love cooking on Sundays.', 10000, 14000, array['dwarka-sector-10', 'dwarka-sector-6', 'vasant-kunj']::text[], array['2BHK', '3BHK']::text[], (now() + interval '2192008 seconds')::date, array['NON_SMOKER', 'VEGETARIAN', 'QUIET']::text[], 'FEMALE', false, null, array['English', 'Hindi']::text[], 'Aerocity', 'aerocity', now() - interval '10800 seconds'),
  ('42dbb1ea-b310-4536-ad15-0501d18b5d01', '796c8195-1078-4b56-a4fa-90f13cdc4015', 'Travel Monday to Thursday for work, so the flat is mostly yours during the week.', 16000, 22000, array['dlf-phase-1', 'gurgaon-sector-43', 'dlf-phase-3']::text[], array['2BHK', '3BHK']::text[], (now() + interval '2192008 seconds')::date, array['SOCIAL', 'NON_VEG_OK', 'GUESTS_OK']::text[], 'ANY', false, null, array['English', 'Hindi']::text[], 'Cyber City, Gurugram', 'cyber-city', now() - interval '28800 seconds'),
  ('f6c63561-5b73-48a8-a833-b488851630c0', 'b0d3cf73-d5a1-4774-a656-4c4fd646d0c4', 'WFH three days a week. I like a calm home, plants and a well-lit desk corner.', 9000, 13000, array['noida-sector-62', 'indirapuram', 'noida-sector-75']::text[], array['2BHK', '3BHK']::text[], (now() - interval '486392 seconds')::date, array['NON_SMOKER', 'VERY_CLEAN', 'WFH']::text[], 'FEMALE', false, null, array['English', 'Hindi']::text[], 'Sector 62, Noida', 'noida-62-it', now() - interval '7200 seconds'),
  ('655ac95a-ef3d-45a4-a4fd-5a53401de7d7', '53a66668-2cf4-4ac6-ab10-0a4a26c9a505', 'Have a 2 BHK in Kalkaji, looking for one working professional to share it.', 12000, 14000, array['kalkaji', 'greater-kailash']::text[], array['2BHK']::text[], (now() - interval '486392 seconds')::date, array['EARLY_RISER', 'FITNESS', 'NO_ALCOHOL']::text[], 'MALE', true, null, array['English', 'Hindi', 'Punjabi']::text[], 'Nehru Place', 'nehru-place', now() - interval '72000 seconds'),
  ('d465fa03-a7a3-4683-aefe-53b147723158', '3696d6a2-f280-40a0-a219-25e321b9fe7f', 'Bookish, quiet, and I make excellent filter coffee.', 13000, 17000, array['lajpat-nagar', 'saket', 'malviya-nagar']::text[], array['2BHK', '3BHK']::text[], (now() + interval '2192008 seconds')::date, array['NON_SMOKER', 'QUIET', 'VEGETARIAN']::text[], 'FEMALE', false, null, array['English', 'Hindi']::text[], 'Okhla', 'okhla', now() - interval '18000 seconds'),
  ('a10221d8-38df-4038-a317-66032c543708', 'd6b71482-7c96-4df3-a748-f10da20496a2', 'Football on weekends, happy to split a cook and a maid.', 8000, 11000, array['gurgaon-sector-14', 'sushant-lok']::text[], array['2BHK', '3BHK']::text[], (now() + interval '2192008 seconds')::date, array['SOCIAL', 'GUESTS_OK', 'NON_VEG_OK']::text[], 'MALE', false, null, array['English', 'Hindi']::text[], 'Udyog Vihar', 'udyog-vihar', now() - interval '108000 seconds'),
  ('58f16a3f-4fba-40d2-ab3a-ba7d3631f7a8', 'c6f4794d-9a20-4b8c-af90-8bdf4cddc877', 'Final-year law student. Need a quiet place close to campus for the exam season.', 8000, 11000, array['kamla-nagar', 'mukherjee-nagar']::text[], array['2BHK']::text[], (now() - interval '486392 seconds')::date, array['NON_SMOKER', 'EARLY_RISER', 'QUIET']::text[], 'FEMALE', false, null, array['English', 'Hindi']::text[], 'DU North Campus', 'du-north-campus', now() - interval '43200 seconds'),
  ('6e8b1a6e-5a31-4cfb-a69b-18e65c3f7711', '9ac00d05-3af8-4e83-a3fe-52f6d5af52cf', 'Night owl developer from Kolkata. Headphones on, dishes done.', 9000, 12000, array['noida-sector-62', 'indirapuram', 'vaishali']::text[], array['2BHK', '3BHK']::text[], (now() + interval '2192008 seconds')::date, array['NIGHT_OWL', 'WFH', 'NON_SMOKER']::text[], 'ANY', false, null, array['English', 'Hindi', 'Punjabi']::text[], 'Sector 62, Noida', 'noida-62-it', now() - interval '1800 seconds'),
  ('3bda9734-e299-41aa-a0ed-01d457209392', '1a978477-d19e-4661-a2af-511137473248', 'Moving from Pune in October. Yoga, podcasts and weekend treks.', 14000, 18000, array['gurgaon-sector-52', 'gurgaon-sector-57', 'gurgaon-sector-43']::text[], array['2BHK', '3BHK']::text[], (now() + interval '2192008 seconds')::date, array['FITNESS', 'VEGETARIAN', 'EARLY_RISER']::text[], 'FEMALE', false, null, array['English', 'Hindi']::text[], 'Golf Course Road', 'golf-course-road', now() - interval '14400 seconds'),
  ('1a903652-be49-48e4-a65d-3bf6a9d5176d', 'afe96dd7-94a5-4946-ad7a-1b8e759485af', 'Preparing for UPSC. Need a disciplined, quiet flatmate.', 7000, 10000, array['mukherjee-nagar', 'kamla-nagar']::text[], array['2BHK']::text[], (now() - interval '486392 seconds')::date, array['QUIET', 'NO_ALCOHOL', 'EARLY_RISER']::text[], 'MALE', false, null, array['English', 'Hindi']::text[], 'Mukherjee Nagar', null, now() - interval '21600 seconds'),
  ('f9612ef8-0dd1-4a1a-a01b-3ae71e2edcae', '3b499b0b-30e4-42e4-ab29-eccef43d9dcc', 'Have a 3 BHK in Hauz Khas with a lovely terrace. One room is free.', 17000, 20000, array['hauz-khas', 'malviya-nagar']::text[], array['3BHK']::text[], (now() - interval '486392 seconds')::date, array['WFH', 'PETS_OK', 'SOCIAL']::text[], 'ANY', true, null, array['English', 'Hindi']::text[], 'Hauz Khas', null, now() - interval '32400 seconds'),
  ('d815e73f-ce01-4730-a8bd-1c6d8c562769', '5f0baa5c-d16c-468b-af1a-3c4b6b5e64c2', 'Just relocated from Jaipur. Easy-going, like cricket and cooking.', 10000, 13000, array['noida-sector-50', 'noida-sector-18', 'noida-sector-75']::text[], array['2BHK']::text[], (now() + interval '2192008 seconds')::date, array['SOCIAL', 'NON_VEG_OK']::text[], 'MALE', false, null, array['English', 'Hindi', 'Punjabi']::text[], 'Sector 125, Noida', 'noida-125', now() - interval '54000 seconds'),
  ('5bb09034-83d5-4cb6-a0ff-d8c5dddb8d16', '4a2ba742-27a7-428d-aff9-e97ebb7bbd3b', 'Looking for a friendly flatmate near a Blue or Yellow line station.', 11000, 15000, array['karol-bagh', 'rajouri-garden', 'laxmi-nagar']::text[], array['2BHK']::text[], (now() + interval '2192008 seconds')::date, array['NON_SMOKER', 'VERY_CLEAN']::text[], 'FEMALE', false, null, array['English', 'Hindi']::text[], 'Connaught Place', 'connaught-place', now() - interval '93600 seconds'),
  ('64faad5f-f455-413a-a1d7-a7b20f156ca3', '76447b50-cb16-44ec-a87e-c7d519cd32f6', 'Chef at an Aerocity hotel — late shifts, but you''ll eat well.', 11000, 14000, array['dwarka-sector-21', 'dwarka-sector-12']::text[], array['2BHK', '3BHK']::text[], (now() + interval '2192008 seconds')::date, array['NIGHT_OWL', 'GUESTS_OK', 'NON_VEG_OK']::text[], 'ANY', false, null, array['English', 'Hindi']::text[], 'Aerocity', 'aerocity', now() - interval '144000 seconds'),
  ('66b2109e-6dca-4894-a68f-f1086202dd15', 'beb43638-f4a1-48ec-ab52-491a64dd0000', 'Irregular hours at the hospital. Looking for a respectful, low-drama home.', 14000, 19000, array['greater-kailash', 'lajpat-nagar', 'malviya-nagar']::text[], array['2BHK', '3BHK']::text[], (now() + interval '2192008 seconds')::date, array['EARLY_RISER', 'QUIET', 'NON_SMOKER']::text[], 'FEMALE', false, null, array['English', 'Hindi']::text[], 'AIIMS', null, now() - interval '25200 seconds'),
  ('38f9dbac-d910-4cb6-ab93-4d037826d73c', 'd3c8843f-81f0-4272-ad2a-a890fe67d915', 'Gym at 6am, in bed by 11. Have a 3 BHK on Golf Course Road with one room free.', 18000, 22000, array['gurgaon-sector-43', 'dlf-phase-1']::text[], array['3BHK']::text[], (now() - interval '486392 seconds')::date, array['FITNESS', 'EARLY_RISER', 'NON_SMOKER']::text[], 'MALE', true, null, array['English', 'Hindi', 'Punjabi']::text[], 'Cyber City, Gurugram', 'cyber-city', now() - interval '10800 seconds'),
  ('f07d78a4-a50a-4383-a4ed-63cfaf592d84', '253babe0-06ea-42cc-a087-9bd1b26ebb06', 'Newsroom hours, dog lover, looking to move closer to Film City.', 12000, 16000, array['noida-sector-18', 'noida-sector-50']::text[], array['2BHK']::text[], (now() + interval '4784008 seconds')::date, array['SOCIAL', 'NIGHT_OWL', 'PETS_OK']::text[], 'ANY', false, null, array['English', 'Hindi']::text[], 'Noida Film City', null, now() - interval '180000 seconds');
