  ('e919f14d-95aa-41ce-a292-ca6c52a3ffb6', '680d085d-2562-41d6-af52-8f446b84c67e', 'fdb0ddb3-74d9-4ce3-abd4-bebc04a5a169', 'About 20 minutes door to door. Can you visit tomorrow?', now() - interval '2400 seconds', null),
  ('4e531b09-fdf8-4728-a762-bff5a68503cd', '9d022217-c2fb-43cf-a63c-7b90fa0113ca', '06638bf4-732a-4924-ab25-e752b3b15308', 'Hi Aisha, I saw your room in Sector 57. I''m a data analyst, vegetarian, non-smoker. Would love to see it this weekend.', now() - interval '18000 seconds', now() - interval '14400 seconds'),
  ('2246b86c-702e-47e1-ab37-7e26a3599040', '9d022217-c2fb-43cf-a63c-7b90fa0113ca', '77d0cad2-5d97-4b2d-aeac-ca6c5010c2c4', 'Hi Priya! Saturday afternoon works. I''ll share the exact address once we confirm a time.', now() - interval '14400 seconds', now() - interval '10800 seconds'),
  ('fdc24157-09c1-45de-a6d3-ec94f5426982', '9d022217-c2fb-43cf-a63c-7b90fa0113ca', '06638bf4-732a-4924-ab25-e752b3b15308', 'Perfect, 4 pm on Saturday?', now() - interval '5400 seconds', null),
  ('d5644b98-599c-41a9-a56e-149557564308', 'e10fd70d-74d3-4212-a9eb-3b2f85f2fff5', '3696d6a2-f280-40a0-a219-25e321b9fe7f', 'Hello! Is the deposit negotiable? Everything else looks perfect.', now() - interval '720 seconds', null);
